CREATE TABLE funcionario (id INTEGER PRIMARY KEY, depto INTEGER,
  salario INTEGER);
INSERT INTO funcionario VALUES (1, 1, 1000), (2, 1, 3000), (3, 2, 6000),
  (4, 2, 8000), (5, 2, 10000);
CREATE VIEW media_depto AS
  SELECT depto, AVG(salario) AS media FROM funcionario GROUP BY depto;
SELECT SUM(f.salario)
FROM funcionario f JOIN media_depto m ON m.depto = f.depto
WHERE f.salario > m.media;

